def find(base, sub, isdir=False):
    out=[]; low=sub.lower().replace("/","\\"); flat=low.replace("\\","")
    if not sub:
        return []
    for dp,dns,fns in os.walk(base):
        dns[:]=[d for d in dns if d not in PRUNE]
        if isdir:
            for d in dns:
                if low in (dp+"\\"+d).lower(): out.append(os.path.join(dp,d))
        for fn in fns:
            full=(dp+"\\"+fn).lower()
            if low in full or flat in fn.lower(): out.append(os.path.join(dp,fn))
    return out[:10]
for tag,repo,sub,needles in Q:
    base=os.path.join(ROOT,repo) if repo else ROOT
    if sub:
        files=find(base,sub)
    else:
        files=[]
        for dp,dns,fns in os.walk(base):
            dns[:]=[d for d in dns if d not in PRUNE]
            for fn in fns:
                if fn.lower().endswith(('.vue','.js','.ts','.py','.java','.md')):
                    files.append(os.path.join(dp,fn))
            if len(files)>4000: break
    corpus=""
    for f in files[:4000]:
        try: corpus+="\n"+open(f,encoding="utf-8",errors="ignore").read()
        except Exception: pass
    nc=re.sub(r"\s+","",corpus).lower()
    marks=[]
    for n in needles:
        q=re.sub(r"\s+","",n).lower()
        marks.append(("Y" if q in nc else "N")+":"+n)
    print(f"{tag} files={len(files)} {' '.join(marks)}")

